(function(){
  const q=(p,o,a,w)=>[p,o,a,w];
  const lesson=(id,title,teach,model,v,qs,w,connect,success,extra={})=>({id,title,src:'Riley ELA binder photographs IMG_0936–IMG_0954 • teacher notes, practice pages, narrative scratch paper, and TNReady Grades 6–8 Narrative Rubric',teach,model,v,q:qs,w,connect,success,...extra});
  const distract=(term,all)=>all.filter(x=>x.term!==term).slice(0,3).map(x=>x.term);
  function vocabLesson(id,title,items){
    const qs=[];
    items.forEach((item,i)=>{
      const pool=[...items.slice(i+1),...items.slice(0,i)];
      qs.push(q(`Which term means “${item.meaning}”?`,[item.term,...distract(item.term,pool)],0,`${item.term}: ${item.meaning}`));
      qs.push(q(`${item.example} Which term is being used or demonstrated?`,[item.term,...distract(item.term,pool.reverse())],0,`${item.term} fits because ${item.why}`));
    });
    return lesson(id,title,
      'These are the teacher’s exact sixth-grade ELA terms. Learn each meaning, its boundary, and how it works in an actual reading or writing task. Similar words are not interchangeable: theme is not a one-word topic; tone is not mood; perspective is not automatically point of view; evidence is not reasoning.',
      `MODEL: “The storm glared through the windows.” The word glared gives the storm a human action, so the device is personification. Naming “figurative language” is too broad; the precise term and the evidence must both be identified.`,
      items.map(x=>[x.term,x.meaning]),qs,
      'Choose six terms without looking. Define each in your own words, create a correct example, give a non-example, and explain the boundary between two commonly confused terms. CONNECTION: Use one task verb to answer a Science or Social Studies question with relevant evidence.',
      'Connect the teacher’s task words to what Riley must actually produce: compare requires similarities and differences, analyze requires parts and relationships, justify requires evidence and reasoning, and formulate requires creating a clear response.',
      'I can recognize, define, distinguish, and apply every term in an unfamiliar passage or prompt.');
  }

  const craft=[
    {term:'main idea / central idea',meaning:'the most important idea an informational text develops',example:'Several details show that repeated practice builds a reader’s confidence.',why:'the statement unifies the important details'},
    {term:'theme',meaning:'a complete message about life or people developed in a literary text',example:'A character admits a mistake after seeing someone else harmed, supporting “Honesty can repair damage.”',why:'it states a message developed through choices and consequences'},
    {term:'point of view',meaning:'the position from which a story is narrated and the information the narrator can reveal',example:'The narrator says “I” and knows only her own thoughts.',why:'first person limits information to the narrator'},
    {term:'simile',meaning:'a comparison using like or as',example:'The rain struck the roof like handfuls of pebbles.',why:'the comparison uses like'},
    {term:'metaphor',meaning:'a direct comparison that says one thing is another',example:'The classroom was a pressure cooker before the quiz.',why:'the comparison is direct'},
    {term:'personification',meaning:'giving human qualities or actions to something nonhuman',example:'The jealous wind shoved at the door.',why:'wind is given a human motive and action'},
    {term:'hyperbole',meaning:'deliberate exaggeration for emphasis, not a literal claim',example:'I waited a million years for the bell.',why:'the impossible exaggeration emphasizes impatience'},
    {term:'alliteration',meaning:'repetition of beginning consonant sounds in nearby words',example:'Wild winds whipped the windows.',why:'the repeated initial w sound creates emphasis'},
    {term:'repetition',meaning:'intentional reuse of a word, phrase, sound, or structure for effect',example:'Never again, never again, she promised.',why:'reusing the phrase emphasizes determination'},
    {term:'onomatopoeia',meaning:'a word whose sound imitates the sound it names',example:'The branch snapped and the pan clanged.',why:'snapped and clanged echo sounds'},
    {term:'tone',meaning:'the author’s or speaker’s attitude toward the subject',example:'Calling the plan “brilliantly careless” creates a critical, sarcastic attitude.',why:'word choice reveals attitude'},
    {term:'mood',meaning:'the feeling or atmosphere a text creates for the reader',example:'Flickering lights and slow footsteps create an uneasy atmosphere.',why:'the details shape the reader’s feeling'},
    {term:'author’s purpose',meaning:'the author’s reason for creating a text, such as informing, explaining, persuading, or entertaining',example:'A passage gives steps and facts about observing chimpanzees.',why:'the author is explaining and informing'},
    {term:'convey',meaning:'to communicate or make an idea, feeling, or information understood',example:'The long pause and lowered eyes communicate regret without naming it.',why:'the details convey regret'}
  ];
  const taskA=[
    {term:'analyze',meaning:'to break something into parts and explain how the parts work or relate',example:'A response explains how the setting, pacing, and dialogue build suspense.',why:'it examines parts and their relationship'},
    {term:'compare',meaning:'to explain meaningful similarities between two or more things',example:'Both the article and video show patient support.',why:'it identifies a shared feature'},
    {term:'contrast',meaning:'to explain meaningful differences between two or more things',example:'The article explains the program goal, while the video shows facial expressions.',why:'it identifies a difference'},
    {term:'infer',meaning:'to reach a supported conclusion from evidence and reasoning',example:'A character hides a broken object and avoids eye contact, so the reader concludes she may feel guilty.',why:'the conclusion is supported but not directly stated'},
    {term:'summarize',meaning:'to state the central idea and essential details concisely and objectively',example:'A response gives the problem, major response, and result without opinions.',why:'it keeps only essential information'},
    {term:'evaluate',meaning:'to judge quality, effectiveness, or credibility using stated criteria and evidence',example:'A reader judges which source better supports a claim and explains why.',why:'the judgment uses criteria'},
    {term:'justify',meaning:'to support an answer or decision with relevant evidence and reasoning',example:'A student cites two details and explains how each proves the claim.',why:'evidence and reasoning defend the answer'},
    {term:'evidence',meaning:'specific information from a text, source, observation, or data set that supports a claim',example:'The phrase “she volunteered to read” supports increased confidence.',why:'it is precise proof from the text'},
    {term:'significant',meaning:'important enough to affect meaning, events, or outcomes',example:'The character’s confession changes who receives the consequence.',why:'the event materially affects the outcome'},
    {term:'consequence',meaning:'a result or effect that follows an action, choice, or event',example:'Because the children locked Margot away, she missed the sun.',why:'missing the sun follows their choice'},
    {term:'factor',meaning:'one condition or element that helps produce or influence a result',example:'Repeated safe practice is one condition influencing reading confidence.',why:'it contributes to the result'},
    {term:'impact',meaning:'the effect or influence something has',example:'The video’s long pause makes the hesitation more noticeable.',why:'it describes an effect on understanding'},
    {term:'method',meaning:'a planned way or technique used to accomplish a task',example:'The observer records time, weather, and location each day.',why:'it is a systematic technique'},
    {term:'process',meaning:'a connected series of steps or changes leading to a result',example:'Decode the prompt, plan, draft, revise, and edit.',why:'the ordered stages lead to a finished response'}
  ];
  const taskB=[
    {term:'perspective',meaning:'a person’s viewpoint, position, or way of seeing a subject',example:'Miss Lesley may interpret the same factory events differently from Grace.',why:'experience and position shape viewpoint'},
    {term:'conclude',meaning:'to reach a final judgment or supported result after considering evidence',example:'After comparing repeated observations, the reader decides the pattern is credible.',why:'the final judgment follows evidence'},
    {term:'determine',meaning:'to find out or decide through evidence, calculation, or reasoning',example:'A reader uses conflict and character change to find the theme.',why:'the answer is established through analysis'},
    {term:'distinguish',meaning:'to recognize and explain the difference between similar things',example:'A student explains that tone is the author’s attitude while mood is the reader’s feeling.',why:'the response separates related concepts'},
    {term:'identify',meaning:'to name or locate something accurately',example:'The reader names the climax in a plot.',why:'the required element is located and named'},
    {term:'contribute',meaning:'to add to, help cause, or play a part in a larger whole',example:'A paragraph describing failed attempts adds evidence for the later success.',why:'the paragraph plays a role in the whole text'},
    {term:'illustrate',meaning:'to explain or make clear with an example, detail, or visual',example:'The author uses Margot’s memory of the sun to show her isolation.',why:'a detail makes the idea clear'},
    {term:'clarify',meaning:'to make an idea easier to understand or remove confusion',example:'The writer adds the speaker’s name so the dialogue is clear.',why:'the revision removes ambiguity'},
    {term:'emphasize',meaning:'to give special importance or attention to something',example:'Repeating “seven years” stresses the length of the wait.',why:'repetition gives the idea extra weight'},
    {term:'formulate',meaning:'to create or develop an idea, plan, or answer carefully',example:'A student develops a claim that can be supported by two details.',why:'the response is deliberately constructed'},
    {term:'develop',meaning:'to build an idea, event, or character with relevant details and explanation',example:'Dialogue, action, and reflection build the turning point instead of merely naming it.',why:'details make the event fuller and clearer'},
    {term:'relevant',meaning:'directly connected to the question, claim, or purpose',example:'A detail about Margot missing the sun supports a claim about exclusion.',why:'the evidence directly supports the claim'},
    {term:'essential',meaning:'absolutely necessary to understanding or completing the task',example:'A summary includes the main conflict but omits the color of a desk.',why:'the conflict is necessary to the main meaning'},
    {term:'emerge',meaning:'to appear, become known, or develop gradually',example:'A pattern becomes clear only after several days of observations.',why:'the pattern gradually becomes visible'}
  ];

  const vocabLessons=[vocabLesson('ela_v26_terms_craft','BINDER FIRST • ELA Terms 1–14: Ideas, Craft, Tone & Purpose',craft),vocabLesson('ela_v26_terms_tasks_a','BINDER FIRST • ELA Terms 15–28: Analysis & Evidence Verbs',taskA),vocabLesson('ela_v26_terms_tasks_b','BINDER FIRST • ELA Terms 29–42: Precision Task Words',taskB)];

  const dialogue=lesson('ela_v26_dialogue','BINDER • Dialogue Punctuation: All 7 Teacher Rules',
    'Rule 1: each new speaker gets a new paragraph; keep that speaker’s nearby actions with the dialogue. Rule 2: capitalize the first word spoken, even when the quotation begins later in the sentence. Rule 3: use a comma between dialogue and a dialogue tag when the spoken sentence would otherwise end with a period. Rule 4: commas, periods, and exclamation points go inside closing quotation marks. Rule 5: put a question mark inside when the spoken words are the question; put it outside when the entire surrounding sentence is the question. Rule 6: when a tag interrupts one spoken sentence, use commas and do not capitalize the continued words. Rule 7: avoid giant blocks of talking; weave dialogue into narration with actions, thoughts, setting, and consequences.',
    'MODEL: “I found it,” Maya said, “but I was afraid to tell you.” The comma stays inside the first closing quotation mark, the tag is lowercase, another comma follows the tag, and but is lowercase because the same sentence continues. New speaker: start a new paragraph.',
    [['dialogue tag','words such as she said that identify the speaker'],['action beat','a character action near dialogue; it is its own sentence'],['interrupted dialogue','one spoken sentence split by a dialogue tag'],['narration','storytelling outside the characters’ spoken words']],
    [
      q('Which format correctly shows a new speaker?',['“Did you hear that?” Ana asked.\n\n“No,” Malik said, turning toward the door.','“Did you hear that?” Ana asked. “No,” Malik said.','“Did you hear that”? Ana asked. “No”, Malik said.','“did you hear that?” Ana asked.\n\n“no,” Malik said.'],0,'Each speaker receives a new paragraph, and punctuation stays inside.'),
      q('Which sentence correctly capitalizes the first spoken word?',['The coach whispered, “Wait for the signal.”','The coach whispered, “wait for the signal.”','The coach whispered “Wait for the signal”.','The coach Whispered, “wait for the signal.”'],0,'The first word of dialogue is capitalized.'),
      q('Which sentence correctly uses a dialogue tag?',['“We should leave,” Nia said.','“We should leave.” Nia said.','“We should leave”, Nia said.','“We should leave” Nia said.'],0,'A comma goes inside the closing quotation mark before a tag.'),
      q('Which sentence places the exclamation point correctly?',['“Run!” Jamal shouted.','“Run”! Jamal shouted.','“Run”! Jamal shouted!','“Run”! shouted Jamal.'],0,'An exclamation point ending the spoken words belongs inside.'),
      q('The spoken words themselves are a question. Which is correct?',['“Are you ready?” she asked.','“Are you ready”? she asked.','“Are you ready,” she asked?','“Are you ready.” she asked.'],0,'The question mark goes inside because the dialogue asks the question.'),
      q('The entire sentence asks whether she said specific words. Which is correct?',['Did she say, “I am ready”?','Did she say, “I am ready?”','Did she say “I am ready.”?','Did she say, “I am ready.”'],0,'The quoted words are a statement; the surrounding sentence is the question.'),
      q('Which interrupted sentence is correct?',['“If we wait,” Mateo said, “the bus may return.”','“If we wait,” Mateo said, “The bus may return.”','“If we wait.” Mateo said, “the bus may return.”','“If we wait”, Mateo said “the bus may return.”'],0,'The same spoken sentence continues, so the second part is lowercase.'),
      q('Which sentence correctly uses an action beat?',['“I can explain.” Tasha stared at the floor.','“I can explain,” Tasha stared at the floor.','“I can explain,” stared Tasha.','“I can explain.” stared Tasha.'],0,'Staring is an action, not a speaking tag.'),
      q('Which revision best follows Rule 7?',['Keep the crucial lines, add reactions and action beats, and show how the exchange changes the scene','Place twelve lines of dialogue together with no action or narration','Delete all narration from the story','Add quotation marks around every narrative sentence'],0,'Dialogue should be woven into a developed scene.'),
      q('ERROR ANALYSIS: “That’s impossible”! she shouted. What must change?',['Move the exclamation point inside the quotation marks','Capitalize she','Add a comma after impossible','Remove the quotation marks'],0,'Exclamation points ending dialogue go inside.'),
      q('ERROR ANALYSIS: “I know,” Ava said, “But I cannot prove it.” What must change?',['Lowercase but because one spoken sentence continues','Move the comma outside','Start a new paragraph after said','Replace the period with a question mark'],0,'The tag interrupts one sentence.'),
      q('SELECT TWO: Which choices help readers follow dialogue?',['Start a new paragraph for each speaker','Use tags or action beats when the speaker is not clear','Keep every speaker in one paragraph','Use giant blocks of speech with no narration'],[0,1],'Paragraphing and purposeful attribution prevent confusion.'),
      q('Which version correctly weaves speech and narration?',['“Don’t open it.” Lila backed away as the box clicked again. “We should call someone.”','“Don’t open it. We should call someone. Why are you touching it? Stop now.”','Lila said “Don’t open it”. she backed away.','“Don’t open it,” backed Lila away.'],0,'The action beat breaks up speech and builds the scene.'),
      q('Which sentence is correct?',['“It’s the spirit of the thing that counts!” shouted Pea.','“It’s the spirit of the thing that counts”! shouted Pea.','“It’s the spirit of the thing that counts”! Shouted Pea.','“It’s the spirit of the thing that counts!” Shouted Pea.'],0,'The punctuation is inside and the tag remains lowercase.'),
      q('Which is punctuated correctly?',['There was a long silence, and then Roscuro said to the queen, “Beg your pardon!”','There was a long silence and then Roscuro said to the queen “beg your pardon”!','There was a long silence, and then Roscuro said, “beg your pardon”!','There was a long silence and then Roscuro said “Beg your pardon”.'],0,'The introductory tag takes a comma and dialogue begins with a capital.'),
      q('A second character replies after the first character’s action. What should the writer do first?',['Begin a new paragraph','Add a semicolon inside the quotation marks','Keep both speakers together','Remove the reply'],0,'Speaker changes require paragraph changes.'),
      q('Why is correct dialogue punctuation important beyond a convention score?',['It shows exactly who speaks, where speech ends, and how the scene moves','It makes every story longer','It replaces character development','It guarantees a happy ending'],0,'Punctuation carries meaning and prevents confusion.'),
      q('Which line uses a comma correctly before a tag?',['“That is all right,” she said, nodding her head.','“That is all right.” she said, nodding her head.','“That is all right”, she said nodding her head.','“That is all right” she said, nodding her head.'],0,'The comma belongs inside before the tag.'),
      q('SELECT TWO: Which marks belong inside when they end spoken words?',['A period','An exclamation point','A question mark when only the whole surrounding sentence is a question','A paragraph break'],[0,1],'Periods and exclamation points ending dialogue stay inside.'),
      q('Which draft needs a new paragraph?',['“I lost it,” Mina said. “You promised to protect it,” Theo answered.','“I lost it,” Mina said, staring at her shoes.','“I lost it!” Mina shouted.','Mina stared down. “I lost it.”'],0,'Theo is a new speaker.'),
      q('Which checklist catches all seven rules?',['speaker paragraphs; first-word capitals; tag commas; marks inside; question location; split-dialogue capitals; narration balance','spelling only','quotation marks only','paragraph length and title only'],0,'The complete checklist matches the teacher page.')
    ],
    'Write a 10–12 sentence scene with two speakers. Use separate paragraphs, a dialogue tag, an action beat, one spoken question, one surrounding-sentence question, and an interrupted line. Underline where each of the seven rules appears. CONNECTION: Explain how dialogue supplies evidence about character and affects plot.',
    'Connect punctuation to character evidence: what a character says, avoids, or interrupts can reveal motivation and move the conflict.',
    'I can edit unfamiliar dialogue and independently write a scene using all seven teacher rules.');

  const prompt=lesson('ela_v26_prompt_plan','BINDER • Attack a TCAP Narrative Prompt + Scratch-Paper Plan',
    'Use the teacher routine in order. First, read the entire prompt. As you reread, circle every task word that tells you what to do. Draw an arrow from each task word to the exact content it controls. Under the prompt, list and number the demands in order. Then build the teacher’s scratch-paper plan: Prompt/checklist; Exposition + Rising Action using known source facts plus new but consistent story information; Climax; Falling Action; Resolution; and one deliberate ending type. A continuation must preserve the assigned narrator, source facts, setting, characterization, and launch situation.',
    'MODEL: “Continue the story from Miss Lesley’s point of view. Use details from Counting on Grace and follow standard English.” Demands: 1 continue—not summarize; 2 Miss Lesley’s point of view; 3 use source details; 4 create a multi-paragraph narrative; 5 use standard conventions. Plan the climax before drafting so events build toward a change instead of wandering.',
    [['task word','a verb telling the writer what to do'],['constraint','a boundary the response must follow'],['continuation','new events that begin where the source ends and remain consistent'],['scratch-paper plan','a brief plot-and-requirements map used before drafting']],
    [
      q('What is the first action with a TCAP-style prompt?',['Read the entire prompt','Write the climax','Choose an ending at random','Copy the title'],0,'The teacher routine begins with reading the full task.'),
      q('What should Riley circle while rereading?',['Words that tell her what to do','Every noun','Only character names','All punctuation'],0,'Task verbs reveal the required work.'),
      q('Why draw an arrow from a task word?',['To connect the verb to the exact content or condition it controls','To decorate the page','To count sentences','To choose the longest word'],0,'The arrow prevents missing a demand.'),
      q('Why number the prompt demands?',['To turn a dense prompt into a checkable ordered list','To decide paragraph length automatically','To replace planning','To rank characters'],0,'Numbering creates a usable checklist.'),
      q('A prompt says “continue where the passage ends.” What must the response do?',['Create new events that logically follow the source ending','Retell the entire passage','Start an unrelated childhood story','Change all established facts'],0,'A continuation begins at the launch point and moves forward.'),
      q('A prompt requires Miss Lesley’s point of view. Which draft violates it?',['Grace narrates with I and reports Miss Lesley’s private thoughts','Miss Lesley narrates what she sees and thinks','The narration uses I for Miss Lesley','Only Miss Lesley’s inner thoughts are revealed'],0,'The assigned narrator must control the perspective.'),
      q('SELECT THREE: Which source elements must a continuation protect?',['Established facts','Assigned point of view','Character traits supported by the passage','A surprise unrelated villain'],[0,1,2],'Continuity requires source consistency and the assigned narrator.'),
      q('What belongs in Exposition + Rising Action on the teacher plan?',['Known source facts plus new, consistent events that build the conflict','Only the final moral','A list of difficult words','The rubric score'],0,'The left planning box builds context and rising events.'),
      q('Why plan the climax before drafting?',['It gives earlier events a clear direction and turning point','It guarantees the climax is in the middle paragraph','It removes the need for conflict','It decides the title'],0,'A planned turning point helps pacing and sequence.'),
      q('What should falling action do?',['Show immediate consequences and movement toward resolution','Introduce a larger unrelated conflict','Repeat the exposition','Stop without showing effects'],0,'Falling action follows the turning point.'),
      q('What should the resolution plan include?',['How the conflict ends or changes and which ending type will create that effect','Every detail from the source','A second climax','A new narrator'],0,'The teacher sheet explicitly pairs resolution with an ending choice.'),
      q('Which plan best fits the Catalina astronomy prompt?',['Continue from the telescope problem, preserve Catalina’s curiosity, and build a multi-paragraph event around what she investigates next','Rewrite Catalina as uninterested in space','Summarize the source and stop','Describe an unrelated sport'],0,'The plan uses the source and launch problem.'),
      q('Which plan best fits a Lighthouse suspense continuation?',['Use established setting, characters, and plot, then extend the suspense toward a believable turning point','Replace the lighthouse with a comedy club without explanation','Explain what suspense means but write no story','Begin before the original passage and never continue it'],0,'The prompt asks for a source-based continuation.'),
      q('What does “use what you learned from the passage” require?',['Integrate relevant source details accurately into the new narrative','Copy the passage word for word','Use only personal experience','Mention the title once'],0,'The source supplies continuity evidence.'),
      q('What does “multi-paragraph narrative” require?',['Organized paragraphs that develop connected events rather than one block','Exactly two sentences','A bulleted summary','A one-line answer'],0,'Paragraphing supports sequence, speakers, and development.'),
      q('ERROR ANALYSIS: A writer circles “write” but misses “from Margot’s point of view” and “multi-paragraph.” What is the risk?',['The response may be a story but still fail task constraints','The spelling will automatically improve','The response will be too objective','The climax will always be correct'],0,'Every demand affects task fulfillment.'),
      q('Which final check best protects the score?',['Match each numbered demand to visible evidence in the draft','Count adjectives only','Choose a different ending after submitting','Delete the plan'],0,'A demand-to-draft check catches omissions.'),
      q('Why should Riley choose the ending type during planning?',['The ending should grow from the conflict, character change, and intended effect','Every story must have a twist','Ending type controls point of view','The ending is unrelated to the plot'],0,'A deliberate ending creates coherence.'),
      q('Which source detail may be invented freely?',['None of the established facts; only new details consistent with them may be created','The assigned narrator','The passage setting','The source conflict'],0,'Creative additions cannot contradict the source.'),
      q('Which sequence matches the teacher plan?',['Prompt checklist → exposition/rising action → climax → falling action → resolution/ending type','Resolution → title → unrelated scene → exposition','Dialogue → grade → prompt → climax','Summary only'],0,'This is the binder’s scratch-paper organization.')
    ],
    'Decode one binder-style prompt. Write a numbered demand list, then complete all five planning areas. Label every source fact, every new but consistent detail, the climax, and the chosen ending type. CONNECTION: Explain how prompt analysis is the same task-verbs skill used in Science and Social Studies.',
    'Connect prompt attack to academic verbs and evidence across subjects: the answer form must match the verb and every condition.',
    'I can independently decode a dense prompt and create a source-faithful, complete plan before drafting.');

  const plot=lesson('ela_v26_plot_conflict','BINDER • Plot Mountain, Conflict & Character Change',
    'Plot is the organized sequence of events in a story. Exposition introduces characters, setting, and the central problem. Rising action is the climb where complications, tension, and excitement grow. The climax is the turning point where the main character faces the conflict and a decision or discovery changes the direction. Falling action shows the immediate results as problems begin to settle. Resolution brings the story to an ending. The binder practices four conflicts: character vs. character/group, character vs. nature, character vs. self, and character vs. technology. Conflict is classified by the force creating the central struggle—not simply by what appears in the scene.',
    'MODEL: In “For the Birds,” the small birds exclude the large bird. Their escalating attempts to remove him are rising action; the release that sends the small birds flying is the climax because it reverses the power and determines the outcome. The central conflict is character vs. character/group, not nature merely because the characters are birds.',
    [['exposition','beginning context: characters, setting, and central problem'],['rising action','complications that increase tension'],['climax','the decisive turning point'],['falling action','consequences following the climax'],['resolution','the outcome or ending'],['conflict','the central struggle driving events']],
    [
      q('Which detail belongs in exposition?',['The setting, key characters, and central problem are introduced','The conflict reaches its decisive turning point','The consequences unfold after the climax','Every question is answered'],0,'Exposition orients the reader and launches the problem.'),
      q('What distinguishes rising action?',['Complications increase tension and push toward the turning point','All problems are already solved','The narrator explains the theme directly','The story ends'],0,'Rising action builds the central struggle.'),
      q('Which event is most likely the climax?',['The character makes the decision that determines how the conflict will end','The setting is introduced','A routine event occurs before the problem','A final sentence names the future'],0,'The climax changes the direction or outcome.'),
      q('What is the function of falling action?',['Show immediate consequences and movement toward resolution','Introduce the main characters','Create the first conflict','Explain background before the story begins'],0,'Falling action follows the turning point.'),
      q('What makes a resolution effective?',['It follows from prior events and shows the conflict’s outcome or remaining effect','It introduces a random larger conflict','It ignores character choices','It repeats the exposition word for word'],0,'An effective ending is earned.'),
      q('A student battles fear about admitting a mistake. Which conflict dominates?',['character vs. self','character vs. nature','character vs. technology','character vs. character'],0,'The struggle occurs within the character.'),
      q('A family must survive a flood. Which conflict dominates?',['character vs. nature','character vs. self','character vs. technology','character vs. character'],0,'The central opposing force is natural.'),
      q('A student’s learning app locks every file and resists every attempt to recover the work. Which conflict dominates?',['character vs. technology','character vs. nature','character vs. self','character vs. character'],0,'Technology creates the central struggle.'),
      q('Two groups compete to control the same space. Which conflict dominates?',['character vs. character/group','character vs. nature','character vs. self','character vs. technology'],0,'People or groups oppose one another.'),
      q('Why is “For the Birds” not character vs. nature merely because birds appear?',['Conflict type depends on the opposing force; the birds oppose one another as characters','Animals always create nature conflict','The setting is outdoors','There is no conflict'],0,'Classification follows the struggle, not character species.'),
      q('What question best locates the climax?',['Which moment forces the decisive change, choice, or reversal?','Which sentence is longest?','Where is the exact middle page?','Which word appears most often?'],0,'The climax is functional, not simply physical middle.'),
      q('SELECT TWO: Which belong in a strong plot analysis?',['Name the event','Explain how it changes the conflict or character','Copy the event with no explanation','Assume every story has identical pacing'],[0,1],'Identification plus function proves analysis.'),
      q('A character is selfish at first, faces the cost of that choice, and shares at the end. What should analysis explain?',['How events and consequences cause or reveal the change','Only the character’s hair color','The page number of the resolution','That every character changes identically'],0,'Character change must be connected to plot evidence.'),
      q('ERROR ANALYSIS: “The climax is the middle because it is on page five of ten.” What is wrong?',['Climax is the turning point, not automatically the physical middle','Climax must always be the final sentence','Page numbers determine conflict type','Every middle event is falling action'],0,'Function determines plot stage.'),
      q('Which sequence is correct?',['exposition → rising action → climax → falling action → resolution','climax → exposition → resolution → rising action → falling action','resolution → rising action → exposition → climax','rising action → resolution → exposition'],0,'The plot mountain shows this sequence.'),
      q('In “All Summer in a Day,” locking Margot away increases the central problem. Where does it belong?',['rising action','resolution','exposition only','long view'],0,'The action escalates conflict before the outcome.'),
      q('When the children remember Margot after the rain returns, the realization mainly functions as',['falling action leading toward the final release','exposition','the first description of Venus','an unrelated flashback'],0,'It follows the sun event and leads to the ending.'),
      q('Which answer connects plot and theme?',['Choices and consequences across the plot can develop a message about exclusion and regret','Theme is always stated in exposition','The longest event becomes the theme','Conflict and theme cannot connect'],0,'The pattern of action and consequence develops meaning.'),
      q('Which resolution best follows a character-vs-self conflict about truth?',['The character admits the truth and accepts what follows','A spaceship lands without connection','The weather changes and the conflict vanishes','A new narrator explains an unrelated event'],0,'The outcome addresses the internal struggle.'),
      q('How does pacing relate to plot?',['Writers often slow down at the climax and compress less important transitions','Every plot stage must have the same length','Exposition must always be one sentence','Resolution requires the most dialogue'],0,'Detail and pace should match importance.')
    ],
    'Create a plot mountain for a familiar story. For every stage, name a specific event and explain its function. Classify the central conflict and trace one character change from beginning to end. CONNECTION: Turn the plot into a cause-and-effect chain with evidence.',
    'Connect plot sequence to cause and effect: rising choices create consequences, the climax changes direction, and the resolution reveals impact.',
    'I can place unfamiliar events by function, classify the central conflict, and explain character change with evidence.');

  const endingDefs=[
    ['explicit','wraps up and answers the major questions, often stating what happens to major characters'],
    ['implicit','leaves the reader to infer the outcome from clues'],
    ['lesson learned','shows the main character grow, change, or learn and often develops a moral-type theme'],
    ['twist','uses a surprising but story-supported event that changes understanding'],
    ['tie back','connects the ending to clues, language, an object, or an event planted near the beginning'],
    ['unresolved','leaves one or more major conflicts unsolved'],
    ['long view','reveals what happens to a character or characters later in the future']
  ];
  const endingQs=[];
  const endingExamples={
    explicit:'The final paragraph explains that the team repaired the damage, apologized, and returned home.',
    implicit:'The door opens; the character smiles at the packed suitcase, but the text never states whether she leaves.',
    'lesson learned':'After losing a friend through dishonesty, the character tells the truth even when it costs him.',
    twist:'The “stranger” removing packages is revealed through earlier clues to be the neighbor protecting them from rain.',
    'tie back':'The story ends with the same paper crane from the opening, now unfolded to reveal the hidden message.',
    unresolved:'The final line stops as the locked box begins to move, with the central danger unanswered.',
    'long view':'Years later, the narrator explains how the decision shaped both friends’ adult lives.'
  };
  endingDefs.forEach(([name,def],i)=>{
    const other=endingDefs.filter(x=>x[0]!==name).slice(i%3,i%3+3).map(x=>x[0]);
    endingQs.push(q(`Which ending type ${def}?`,[name,...other],0,`${name}: ${def}`));
    endingQs.push(q(`${endingExamples[name]} Which ending type is used?`,[name,...other.slice().reverse()],0,`The example uses a ${name} ending.`));
    endingQs.push(q(`Which description is a boundary of a ${name} ending?`,[
      name==='twist'?'The surprise should be supported by prior events rather than random':name==='implicit'?'The text supplies clues even though it does not state the outcome':name==='unresolved'?'The conflict remains open intentionally, not because the writer forgot to finish':name==='tie back'?'The repeated element gains meaning from its earlier appearance':name==='lesson learned'?'The change must grow from events and consequences':name==='explicit'?'Major questions are answered without needing to explain every tiny detail':'The future information must connect to the central characters and conflict',
      'It can ignore every earlier event','It always requires a new narrator','It is determined only by story length'
    ],0,'Ending type depends on function and evidence, not a label alone.'));
  });
  const endings=lesson('ela_v26_endings','BINDER • Seven Story Endings: Identify, Defend & Rewrite',
    'The binder names seven ending types: explicit, implicit, lesson learned, twist, tie back, unresolved, and long view. An ending can show more than one quality, so classify it by its strongest function and defend the choice with precise clues. Explicit answers major questions; implicit requires inference; lesson learned shows change; twist surprises using planted evidence; tie back reconnects to the opening; unresolved leaves major conflict open; long view moves into the future.',
    'MODEL: “Years later, Lina still kept the cracked compass above her desk.” This is primarily long view because it tells what happens later. It also ties back to the compass, but the time jump is the strongest structural effect. A strong answer names the type, cites the clue, and explains the effect.',
    endingDefs,endingQs,
    'Write seven two-sentence endings for one shared story situation—one of each type. Label each, underline the feature that proves the type, and explain the intended effect. CONNECTION: Explain how the ending completes or deliberately leaves open the plot’s cause-and-effect chain.',
    'Connect ending choice to character change, theme, and reader inference; the ending must grow from the conflict rather than appear as a detached trick.',
    'I can distinguish all seven types, defend classifications with evidence, and deliberately create each type.');

  const rubric=lesson('ela_v26_rubric','BINDER • TN Narrative Rubric: Score, Revise & Prove',
    'The teacher binder uses the TNReady Grades 6–8 Narrative Rubric. Four domains control revision. Focus & Organization: answer the exact task, orient the reader with relevant context and point of view, introduce narrator/characters, sequence events naturally, use transitions, and conclude effectively. Development: use relevant dialogue, pacing, description, and reflection to develop experiences, events, and characters and incorporate source details. Language: use precise and sensory language, varied sentence structures, and purposeful transitions. Conventions: control sentence structure, grammar, usage, spelling, capitalization, and punctuation. A vivid response can still score poorly if it violates the prompt.',
    'MODEL: Draft: “I was scared. I went in. I told her.” Diagnosis: focused but underdeveloped. Revision: add the exact turning-point action, one purposeful line of dialogue, sensory detail, and reflection. Then check quotation marks and sentence boundaries. The repair targets Development, Language, and Conventions without changing the prompt.',
    [['focus and organization','task fulfillment, context, point of view, logical sequence, transitions, and conclusion'],['development','narrative techniques and relevant source details that build events and characters'],['language','precise/sensory wording, sentence variety, and transitions'],['conventions','grammar, usage, spelling, capitalization, sentence structure, and punctuation']],
    [
      q('A vivid response switches narrators even though the prompt requires Margot’s first person. What needs first repair?',['focus and organization','language only','spelling only','title design'],0,'Task and point-of-view compliance come first.'),
      q('A story names the climax but rushes through it in one vague sentence. Which domain needs the strongest repair?',['development','conventions only','font choice','source title'],0,'Pacing, dialogue, description, and reflection develop the experience.'),
      q('A writer replaces “went” with “edged across the wet floor.” Which domain is most directly improved?',['language','focus only','source fidelity only','paragraph count'],0,'Precise and sensory wording improves language.'),
      q('Missing capitals and dialogue marks primarily affect',['conventions','theme','point of view','plot sequence'],0,'Capitalization and punctuation are conventions.'),
      q('Which evidence best supports a strong Focus & Organization score?',['The narrator, context, logical sequence, transitions, and conclusion all answer the assigned task','The title uses a decorative font','Every paragraph has the same length','The story has one difficult word'],0,'The domain measures task control and structure.'),
      q('Which evidence best supports a strong Development score?',['Dialogue, pacing, description, reflection, and source details purposefully build the central event','The response is long','There are many adjectives','The first sentence repeats the prompt'],0,'Purposeful techniques—not length alone—develop the narrative.'),
      q('Which evidence best supports a strong Language score?',['Precise sensory details and varied syntax create meaning and reader interest','Every sentence begins with I','The story uses the word very often','The font is small'],0,'Language is measured through precise words and sentence craft.'),
      q('Which evidence best supports a strong Conventions score?',['Sentence boundaries, grammar, spelling, capitalization, and punctuation are consistently controlled','The climax is surprising','The character changes','The passage has five paragraphs'],0,'These are standard-English conventions.'),
      q('SELECT TWO: Which are narrative techniques named by the rubric?',['dialogue','pacing','a bibliography','a data table'],[0,1],'The rubric names dialogue and pacing, along with description and reflection.'),
      q('Why is source fidelity part of Development in a passage-based narrative?',['Relevant, accurate stimulus details must be incorporated to develop the new story','The source may be replaced with personal facts','Copying the source is enough','Source details determine spelling'],0,'The narrative must show understanding of the stimulus.'),
      q('Which conclusion is strongest?',['It follows from events and reflects on the experience or shows its outcome','It introduces an unrelated conflict','It repeats the prompt only','It stops because the word count is reached'],0,'The rubric expects an effective conclusion tied to events.'),
      q('What is reflection?',['Thinking that shows the meaning or effect of an experience','A mirror in the setting','A repeated title','A dialogue tag'],0,'Reflection helps readers understand significance.'),
      q('ERROR ANALYSIS: A story has perfect punctuation but ignores the assigned point of view. Is it ready?',['No; conventions cannot compensate for failure to answer the task','Yes; punctuation is the only domain','Yes; length matters most','No; narratives cannot use point of view'],0,'Domains are distinct; task fulfillment is essential.'),
      q('Which revision is targeted rather than decorative?',['Add a reaction and decision at the turning point to clarify character change','Add five random adjectives','Change the font','Insert an unrelated dream'],0,'A targeted revision solves a diagnosed rubric problem.'),
      q('Which transition shows a clear time relationship?',['By the following afternoon','Very interestingly','Blue and beautiful','Suddenly suddenly'],0,'The phrase clarifies sequence.'),
      q('Which sentence adds precise sensory language?',['Cold rain needled the back of my neck as the metal latch stuck under my thumb.','It was bad outside.','Something happened near the door.','I felt a feeling.'],0,'The detail appeals to touch and sight precisely.'),
      q('Which sentence shows varied syntax?',['Although the hallway was silent, the locker door trembled against its frame.','I walked. I looked. I stopped. I waited.','Very very very quiet.','The hallway because silent.'],0,'The dependent opening varies structure while remaining clear.'),
      q('What should Riley do after revising dialogue?',['Reread the surrounding paragraph for meaning, speaker clarity, and punctuation','Assume every change works','Delete all narration','Change the narrator'],0,'Revision requires a full-context check.'),
      q('Which self-check uses the rubric correctly?',['Name the domain, cite an exact draft feature, judge it, and make a targeted repair','Say “looks good” without evidence','Count words only','Choose the score wanted'],0,'Rubric judgment must be evidence-based.'),
      q('What would prove independent narrative readiness?',['A complete source-based narrative plus evidence-based self-scoring in all four domains','Selected-response answers only','A copied model','A plot diagram with no draft'],0,'Writing must be demonstrated through actual writing.')
    ],
    'Write or revise a multi-paragraph continuation. Then create a four-row audit: one exact piece of evidence for each rubric domain, the likely score level, one weakness, and the targeted revision. CONNECTION: Compare this error-analysis process with correcting a Math or Science response.',
    'Connect rubric revision to error analysis: identify the exact failure, explain why it matters, repair only what is needed, and recheck the whole response.',
    'I can draft, score, and revise an independent narrative using evidence for every rubric domain.');

  const allTerms=[...craft,...taskA,...taskB];
  const independentQs=allTerms.map((item,i)=>q(`${item.example} Choose the most precise binder term.`,[item.term,...distract(item.term,[...allTerms.slice(i+1),...allTerms.slice(0,i)])],0,`${item.term}: ${item.why}`));
  independentQs.push(
    q('Which sequence matches the plot mountain?',['exposition → rising action → climax → falling action → resolution','rising action → exposition → ending → climax','climax → resolution → exposition → rising action','resolution → exposition → climax'],0,'This is the teacher sequence.'),
    q('Which ending leaves the outcome for the reader to infer from clues?',['implicit','explicit','long view','lesson learned'],0,'Implicit endings require inference.'),
    q('Which ending leaves a major conflict unsolved?',['unresolved','explicit','tie back','long view'],0,'Unresolved endings intentionally keep a major conflict open.'),
    q('Which ending returns to an opening clue or object?',['tie back','long view','implicit','explicit'],0,'Tie back reconnects beginning and end.'),
    q('Which sentence correctly interrupts one line of dialogue?',['“When the rain stops,” Margot said, “I want to go outside.”','“When the rain stops,” Margot said, “I Want to go outside.”','“When the rain stops.” Margot said, “I want to go outside.”','“When the rain stops”, Margot said “I want to go outside.”'],0,'The tag interrupts one sentence.'),
    q('Which step comes immediately after circling task words in the teacher prompt routine?',['Draw arrows to what each word requires','Draft without planning','Choose a grade','Write the resolution'],0,'Arrows link verbs to their demands.'),
    q('Which conflict is central when a character struggles with guilt?',['character vs. self','character vs. nature','character vs. technology','character vs. character'],0,'Guilt is an internal struggle.'),
    q('Which rubric domain includes pacing, dialogue, description, and reflection?',['development','conventions','focus only','formatting'],0,'These narrative techniques develop the experience.'),
    q('Which rubric domain includes spelling, capitalization, grammar, sentence boundaries, and punctuation?',['conventions','development','theme','plot'],0,'These are standard-English conventions.'),
    q('Which response best explains the ending of “All Summer in a Day”?',['It is unresolved because Margot is released, but the central harm and what happens between the children remain open','It is explicit because every major question is answered','It is long view because many years pass after she is released','It is a twist because no earlier event supports the ending'],0,'The final release does not resolve the emotional and relational conflict.'),
    q('SELECT THREE: Which belong in a source-based continuation plan?',['accurate source facts','the assigned point of view','a deliberate climax','contradictory character behavior with no explanation'],[0,1,2],'Source accuracy, viewpoint, and plot direction are required.'),
    q('Which classification and evidence pairing is strongest?',['climax—the decision reverses the conflict and determines the outcome','climax—the event occurs on the middle page','resolution—the characters are first introduced','exposition—the consequences unfold'],0,'Plot stages are identified by function.'),
    q('Which version correctly asks whether a character spoke a statement?',['Did Margot say, “I remember the sun”?','Did Margot say, “I remember the sun?”','Did Margot say “I remember the sun.”?','Did Margot say, “I remember the sun.”'],0,'The whole sentence, not the spoken words, is the question.'),
    q('What is the strongest final readiness evidence?',['A fresh narrative that meets every prompt demand and all four rubric domains','A memorized list alone','A copied model','One correctly punctuated line'],0,'Independent transfer proves readiness.')
  );
  const finalTest=lesson('ela_v26_binder_final','FINAL • ELA Binder Readiness: 56 Independent Questions + Narrative',
    'Closed note. This form samples all 42 teacher terms plus dialogue, prompt attack, plot, conflict, endings, and the Tennessee narrative rubric. It comes after instruction. A selected-response score does not replace the required independent narrative.',
    '',[],independentQs,
    'INDEPENDENT WRITING: Continue “All Summer in a Day” from Margot’s point of view immediately after the closet opens. Preserve source facts and characterization; use the teacher scratch-paper plan; develop a clear plot and conflict; include purposeful, correctly punctuated dialogue; choose and execute one of the seven ending types; then self-score all four rubric domains with exact evidence. CONNECTION: Explain how your plan uses cause/effect and evidence.',
    'This assessment connects reading analysis to writing craft: vocabulary names the decisions, source evidence constrains them, and the rubric evaluates execution.',
    'Ready means at least 51/56 on first attempt, correction of every miss, an independently completed narrative meeting every prompt demand, and successful delayed retrieval.',{test:true,mix:true});

  const allSummer=lesson('ela_v26_all_summer_end','BINDER APPLICATION • “All Summer in a Day”: Plot, Ending & Rewrite',
    'At the end of Ray Bradbury’s story, the rain returns, the children remember Margot, walk to the closet, and release her. The binder classifies the ending as unresolved: the physical act of opening the door occurs, but the central emotional and relational questions remain open. Will the children apologize? How will Margot respond? Can the harm be repaired? A defensible answer must identify the ending type, cite precise ending evidence, and explain what remains unresolved. Then Riley must be able to redesign the ending as another of the seven types without contradicting the source.',
    'MODEL: Claim—unresolved ending. Evidence—the children cannot meet one another’s eyes, walk slowly, and release Margot without the text showing her response. Reasoning—the actions show guilt but leave the central relationship and consequences unanswered. Rewrite as lesson learned: one child admits the harm, acts differently, and the change follows from guilt already shown.',
    [['source fidelity','keeping established facts, setting, characterization, and events accurate'],['ending evidence','specific final details that reveal an ending’s type and effect'],['redesign','changing the ending’s structure while preserving the story’s established world']],
    [
      q('What type of ending does the binder assign to “All Summer in a Day”?',['unresolved','explicit','long view','tie back'],0,'The central emotional and relational conflict remains open.'),
      q('Which evidence best supports that classification?',['The children release Margot, but her response and the consequences of their cruelty are not shown','The rain begins again','The story takes place on Venus','The sun appeared earlier'],0,'The missing outcome concerns the central conflict.'),
      q('Why is the ending not fully explicit?',['It does not answer the major questions about Margot’s response, apology, or repair','It contains no characters','It explains every future event','It uses first person'],0,'An explicit ending answers the major questions.'),
      q('What do the children’s lowered faces and avoided glances allow readers to infer?',['They feel guilt or shame','They have forgotten Margot','They are celebrating','They do not hear the rain'],0,'Behavior supplies evidence of guilt.'),
      q('Which rewrite creates a lesson-learned ending?',['A child admits the cruelty, apologizes, and makes a changed choice that grows from the experience','A meteor destroys Venus','The story stops before the closet opens','Years later, the narrator lists careers'],0,'Character growth and a moral consequence define lesson learned.'),
      q('Which rewrite creates a long-view ending?',['Years later, Margot explains how the day affected her trust and the classmates’ lives','The closet opens and the page stops','A surprising stranger appears','The final line repeats an opening phrase'],0,'A long view reveals later outcomes.'),
      q('Which rewrite creates a tie-back ending?',['The final image returns to the sun poem or remembered warmth introduced earlier and gives it new meaning','The ending explains every character’s future','A random alarm sounds','The conflict remains entirely open'],0,'Tie back reconnects to a planted element.'),
      q('Which rewrite creates an explicit ending?',['The children apologize, Margot responds, and the text clearly states the immediate outcome','The door opens but no response is shown','Readers infer an outcome from a shadow','The story jumps ahead twenty years'],0,'Major questions receive direct answers.'),
      q('Which rewrite creates an implicit ending?',['Margot studies their lowered faces, places her hand on the door, and steps past them without speaking','A narrator states exactly what everyone does next','The conflict remains with no clues','Years later, Margot explains the outcome'],0,'Clues invite inference without stating the outcome.'),
      q('Which twist would be fair rather than random?',['A surprise that grows from an earlier detail or pattern in the story','An unrelated dragon arrives','Earth suddenly replaces Venus','A narrator contradicts every source fact'],0,'A valid twist is surprising but supported.'),
      q('SELECT TWO: Which requirements protect a rewrite?',['Preserve established source facts','Make the new ending grow from existing conflict and characterization','Change Venus into Earth without explanation','Ignore Margot’s established experience'],[0,1],'A redesign changes structure, not the source’s foundation.'),
      q('Which conflict drives the ending most directly?',['character vs. character/group, with an internal guilt component','character vs. technology only','character vs. nature only','no conflict'],0,'The group’s treatment of Margot is central; guilt adds internal struggle.'),
      q('Which event is the most defensible climax of the broader story?',['The children experience the sun while Margot remains locked away, making the harm irreversible','The first description of rain','The classroom is introduced','The final closet door opens'],0,'The peak experience and cruel exclusion determine the story’s consequences.'),
      q('What should a strong 1–2 sentence binder response include?',['ending type + precise evidence + reasoning about what remains open','ending type only','personal preference only','a full retelling'],0,'Classification must be defended.'),
      q('Which response uses evidence rather than opinion?',['The avoided glances and slow walk show guilt, but the story never reveals Margot’s reaction','I dislike sad endings','The ending should be happier','Venus sounds unpleasant'],0,'It cites textual behavior and explains its meaning.'),
      q('Why does changing the ending affect theme?',['The final consequence or character response can emphasize regret, repair, justice, or uncertainty differently','Theme depends only on title','All ending types create the same message','Theme is unrelated to character change'],0,'Ending choices shape the message readers carry away.')
    ],
    'Write the binder’s 1–2 sentence defense of the original ending. Then rewrite the ending as one different type. Label the new type, preserve source facts, include correctly punctuated dialogue, and explain how the new ending changes theme and character impact. CONNECTION: Trace action → consequence → inference.',
    'Connect the ending to inference, theme, character change, and source evidence rather than treating it as an isolated label.',
    'I can defend the original ending and create a source-faithful alternative with a deliberate effect.');

  dialogue.sourceRequirements=['seven dialogue rules','new speaker paragraph','capitalize first word of dialogue','comma with dialogue tag','dialogue punctuation inside quotation marks','question mark placement with dialogue','interrupted dialogue capitalization','weave dialogue into narration'];
  prompt.sourceRequirements=['read circle arrow number prompt routine','narrative scratch-paper plan'];
  plot.sourceRequirements=['exposition','rising action','climax','falling action','resolution','character versus character','character versus nature','character versus self','character versus technology','character change across plot'];
  endings.sourceRequirements=['explicit ending','implicit ending','lesson learned ending','twist ending','tie back ending','unresolved ending','long view ending'];
  allSummer.sourceRequirements=['all summer in a day unresolved ending evidence'];
  rubric.sourceRequirements=['focus and organization rubric domain','development rubric domain','language rubric domain','conventions rubric domain'];
  finalTest.sourceRequirements=['independent source-based narrative'];
  D.ELA.lessons.unshift(...vocabLessons,dialogue,prompt,plot,endings,allSummer,rubric,finalTest);
  globalThis.ELA_BINDER_V26={version:'2026-10-19-ela-binder-source-reconciliation-v26',lessons:10,terms:42,dialogueRules:7,endingTypes:7,finalQuestions:independentQs.length};
})();
